+function segmentRegExp(segment: string): RegExp {
+  let source = "^";
+  for (const ch of segment) {
+    if (ch === "*") {
+      source += "[^/]*";
+    } else if (ch === "?") {
+      source += "[^/]";
+    } else {
+      source += REGEX_SPECIALS.has(ch) ? `\\${ch}` : ch;
+    }
+  }
+  return new RegExp(`${source}$`);
+}
